#include "WebServer.h"
#include <LittleFS.h>
RadarWebServer::RadarWebServer():_server(80){}bool RadarWebServer::begin(){_filesystemReady=LittleFS.begin(true);if(!_filesystemReady){Serial.println("[LittleFS] Falha ao montar o sistema de arquivos.");return false;}_server.on("/health",HTTP_GET,[](AsyncWebServerRequest* request){request->send(200,"application/json","{\"ok\":true,\"service\":\"smart-radar\"}");});_server.serveStatic("/",LittleFS,"/").setDefaultFile("index.html");_server.onNotFound([](AsyncWebServerRequest* request){if(LittleFS.exists("/index.html"))request->send(LittleFS,"/index.html","text/html");else request->send(404,"text/plain","Smart Radar UI not found");});return true;}void RadarWebServer::start(){_server.begin();Serial.println("[HTTP] Servidor web iniciado na porta 80.");}
